// Des: Drive one Chrome tab: navigate, settle, read the final DOM
// Flo: enable domains > Page.navigate > wait load event > poll text length until stable > optional wait + selector > flatten open shadow roots to HTML > snapshot text when closed roots exist
// I/O: Conn (caller) + URL + Opt > HTML text of the rendered page, JS error count; eval helpers for other modules
// ===================================================================
const std = @import("std"); const mem2 = std.mem; const cdp2 = @import("nt-brow-cdpz.zig");
const CF = .{ .step = 250, .calm = 2, .flat = "(function(){function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}function ser(n){if(n.nodeType===3)return esc(n.nodeValue);if(n.nodeType!==1)return '';var t=n.tagName.toLowerCase();if(t==='script'||t==='style'||t==='noscript'||t==='template')return '';var a='';for(var i=0;i<n.attributes.length;i++){var at=n.attributes[i];a+=' '+at.name+'=\"'+at.value.replace(/\"/g,'&quot;')+'\"'}var c='';if(n.shadowRoot){for(var j=0;j<n.shadowRoot.childNodes.length;j++)c+=ser(n.shadowRoot.childNodes[j])}for(var k=0;k<n.childNodes.length;k++)c+=ser(n.childNodes[k]);return '<'+t+a+'>'+c+'</'+t+'>'}return '<!DOCTYPE html>'+ser(document.documentElement)})()", .skip = @as([]const []const u8, &.{ "SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE" }) };
pub const Optz = struct { time_mill: u32 = 60000, wait: u32 = 0, sele: []const u8 = "", blok: bool = false };
pub const Rend = struct { html: []const u8, errs: u32, clo3: bool };
pub const Page = struct { conn: *cdp2.Conn, gpaz: std.mem.Allocator, iozz: std.Io, dead: i64 = 0,
pub fn left(self: *Page) u32 { const remz = self.dead - cdp2.nowzMill(self.iozz); return if (remz <= 0) 0 else @intCast(remz); }
pub fn evalValu(self: *Page, aren: std.mem.Allocator, expr: []const u8) !std.json.Value { const prmz = try std.json.Stringify.valueAlloc(aren, .{ .expression = expr, .returnByValue = true, .awaitPromise = true }, .{}); const rslt = try self.conn.callJson(aren, "Runtime.evaluate", prmz, @max(self.left(), 1)); if (rslt != .object) return error.CdpError; if (rslt.object.get("exceptionDetails") != null) return error.EvalFail; const out2 = rslt.object.get("result") orelse return error.CdpError; if (out2 != .object) return error.CdpError; return out2.object.get("value") orelse .null; }
pub fn evalStrz(self: *Page, aren: std.mem.Allocator, expr: []const u8) ![]const u8 { const val2 = try self.evalValu(aren, expr); return switch (val2) { .string => |tex2| tex2, .integer => |num2| try std.fmt.allocPrint(aren, "{d}", .{num2}), .bool => |flgz| if (flgz) "true" else "false", else => "" }; }
pub fn evalNumb(self: *Page, aren: std.mem.Allocator, expr: []const u8) i64 { const val2 = self.evalValu(aren, expr) catch return -1; return switch (val2) { .integer => |num2| num2, .float => |fltz| @intFromFloat(fltz), .bool => |flgz| if (flgz) 1 else 0, else => 0 }; }
pub fn napz(self: *Page, mill: u32) void { std.Io.sleep(self.iozz, .fromMilliseconds(@min(mill, self.left())), .awake) catch {}; }
pub fn sett(self: *Page, aren: std.mem.Allocator) void { var prev: i64 = -2; var same: u32 = 0; while (self.left() > 0) { const curr = self.evalNumb(aren, "document.body?document.body.innerText.length:0"); if (curr == prev) { same += 1; if (same >= CF.calm) return; } else same = 0; prev = curr; self.napz(CF.step); } }
pub fn navi(self: *Page, aren: std.mem.Allocator, urlz: []const u8, optz: Optz) !void { self.dead = cdp2.nowzMill(self.iozz) + optz.time_mill; for ([_][]const u8{ "Page.enable", "Runtime.enable", "Log.enable" }) |mthz| _ = try self.conn.callJson(aren, mthz, "", @max(self.left(), 1)); if (optz.blok) { _ = try self.conn.callJson(aren, "Network.enable", "", @max(self.left(), 1)); _ = try self.conn.callJson(aren, "Network.setBlockedURLs", "{\"urls\":[\"*.png\",\"*.jpg\",\"*.jpeg\",\"*.gif\",\"*.webp\",\"*.svg\",\"*.ico\",\"*.woff\",\"*.woff2\",\"*.ttf\",\"*.mp4\",\"*.webm\",\"*.mp3\"]}", @max(self.left(), 1)); } var from: usize = self.conn.evzzCoun(); const prmz = try std.json.Stringify.valueAlloc(aren, .{ .url = urlz }, .{}); const rslt = try self.conn.callJson(aren, "Page.navigate", prmz, @max(self.left(), 1)); if (rslt == .object) { if (rslt.object.get("errorText") != null) return error.NavFail; } _ = try self.conn.evzzWait(aren, "Page.loadEventFired", &from, @max(self.left(), 1)); self.sett(aren); if (optz.wait > 0) self.napz(optz.wait); if (optz.sele.len > 0) { const qryz = try std.json.Stringify.valueAlloc(aren, optz.sele, .{}); const expr = try std.fmt.allocPrint(aren, "document.querySelector({s})!==null", .{qryz}); while (self.left() > 0) { if (self.evalNumb(aren, expr) == 1) break; self.napz(CF.step); } } }
fn nodeSkip(strs: []const std.json.Value, ntyp: []const std.json.Value, nnam: []const std.json.Value, parz: []const std.json.Value, ind2: usize) bool { var curr: i64 = @intCast(ind2); var hops: usize = 0; while (curr >= 0 and hops < 64) : (hops += 1) { const uixz: usize = @intCast(curr); if (ntyp[uixz] == .integer and ntyp[uixz].integer == 1 and nnam[uixz] == .integer) { const nixz = nnam[uixz].integer; if (nixz >= 0 and @as(usize, @intCast(nixz)) < strs.len and strs[@intCast(nixz)] == .string) { for (CF.skip) |skzz| if (std.ascii.eqlIgnoreCase(skzz, strs[@intCast(nixz)].string)) return true; } } curr = if (parz[uixz] == .integer) parz[uixz].integer else -1; } return false; }
pub fn snapText(self: *Page, aren: std.mem.Allocator) !struct { text: []const u8, clo3: bool } { const rslt = try self.conn.callJson(aren, "DOMSnapshot.captureSnapshot", "{\"computedStyles\":[]}", @max(self.left(), 1)); if (rslt != .object) return error.CdpError; const strv = rslt.object.get("strings") orelse return error.CdpError; const docs = rslt.object.get("documents") orelse return error.CdpError; if (strv != .array or docs != .array) return error.CdpError; var outp: std.ArrayList(u8) = .empty; var clo3 = false; for (docs.array.items) |docz| { if (docz != .object) continue; const node = docz.object.get("nodes") orelse continue; if (node != .object) continue; if (node.object.get("shadowRootType")) |srtz| { if (srtz == .object) { if (srtz.object.get("value")) |vals| { if (vals == .array) { for (vals.array.items) |vizz| { if (vizz == .integer and vizz.integer >= 0 and @as(usize, @intCast(vizz.integer)) < strv.array.items.len) { const svzz = strv.array.items[@intCast(vizz.integer)]; if (svzz == .string and mem2.eql(u8, svzz.string, "closed")) clo3 = true; } } } } } } const ntyp = (node.object.get("nodeType") orelse continue); const nval = (node.object.get("nodeValue") orelse continue); const nnam = (node.object.get("nodeName") orelse continue); const parz = (node.object.get("parentIndex") orelse continue); if (ntyp != .array or nval != .array or nnam != .array or parz != .array) continue; const con2 = @min(@min(ntyp.array.items.len, nval.array.items.len), @min(nnam.array.items.len, parz.array.items.len)); for (0..con2) |ind3| { if (ntyp.array.items[ind3] != .integer or ntyp.array.items[ind3].integer != 3) continue; if (nval.array.items[ind3] != .integer) continue; const sizz = nval.array.items[ind3].integer; if (sizz < 0 or @as(usize, @intCast(sizz)) >= strv.array.items.len) continue; const svzz = strv.array.items[@intCast(sizz)]; if (svzz != .string) continue; if (nodeSkip(strv.array.items, ntyp.array.items[0..con2], nnam.array.items[0..con2], parz.array.items[0..con2], ind3)) continue; const trmz = mem2.trim(u8, svzz.string, " \t\r\n"); if (trmz.len == 0) continue; try outp.appendSlice(aren, trmz); try outp.append(aren, '\n'); } } return .{ .text = outp.items, .clo3 = clo3 }; }
fn esczHtml(aren: std.mem.Allocator, tex2: []const u8) ![]u8 { var outp: std.ArrayList(u8) = .empty; for (tex2) |chr2| switch (chr2) { '&' => try outp.appendSlice(aren, "&amp;"), '<' => try outp.appendSlice(aren, "&lt;"), '>' => try outp.appendSlice(aren, "&gt;"), else => try outp.append(aren, chr2) }; return outp.toOwnedSlice(aren); }
pub fn errzCoun(self: *Page) u32 { return self.conn.evzzHasz("Runtime.exceptionThrown") + self.conn.evzzHasz("\"level\":\"error\""); }
pub fn grab(self: *Page, aren: std.mem.Allocator) !Rend { const flat = try self.evalStrz(aren, CF.flat); const snpz = self.snapText(aren) catch return .{ .html = flat, .errs = self.errzCoun(), .clo3 = false }; if (!snpz.clo3) return .{ .html = flat, .errs = self.errzCoun(), .clo3 = false }; const titl = self.evalStrz(aren, "document.title") catch ""; var outp: std.ArrayList(u8) = .empty; try outp.print(aren, "<!DOCTYPE html><html><head><title>{s}</title></head><body>", .{try esczHtml(aren, titl)}); var itrz = mem2.splitScalar(u8, snpz.text, '\n'); while (itrz.next()) |lnzz| { if (lnzz.len == 0) continue; try outp.print(aren, "<p>{s}</p>", .{try esczHtml(aren, lnzz)}); } try outp.appendSlice(aren, "</body></html>"); return .{ .html = outp.items, .errs = self.errzCoun(), .clo3 = true }; }
};
pub fn pageOpen(gpaz: std.mem.Allocator, iozz: std.Io, port: u16, wspa: []const u8, mill: u32) !Page { const conn = try cdp2.connect(gpaz, iozz, port, wspa, mill); return .{ .conn = conn, .gpaz = gpaz, .iozz = iozz }; }
